   "  BUY AN ITEM",             // 5
   "  SELL AN ITEM",            // 6
   " HDE MAIN DISPLAY"          // 7
   };

#define BUY_MODE  0
#define SELL_MODE 1

PRIVATE INT mode        =  BUY_MODE;
PRIVATE INT cur_item    =  0;
