   else
   {
      SWD_SetFieldItem ( window, STOR_BUY, buybut [1] );
      SWD_SetFieldItem ( window, STOR_SELL, sellbut [0] );
   }

   SWD_ShowAllWindows();
   GFX_DisplayUpdate();
   update = TRUE;

   mainloop:

   MakeSellItems();
   MakeBuyItems();
  
   if ( mode == BUY_MODE )
      max_items = buy_count;
…
}

