46:/*-------------------------------------------------------------------------*
47:TClear () - Clears TILE Delay Link List
48: *-------------------------------------------------------------------------*/
49:PRIVATE VOID
50:TClear (
51:VOID
52:)
53:{
54:   INT loop;
55:  
56:   first_delay.prev = NUL;
57:   first_delay.next = &last_delay;
58:  
59:   last_delay.prev = &first_delay;
60:   last_delay.next = NUL;
61:  
62:   free_delay = tdel;
63:  
64:   memset ( tdel, 0, sizeof ( tdel ) );
65:  
66:   for ( loop = 0; loop < MAX_TILEDELAY-1; loop++ )
67:      tdel[ loop ].next = &tdel [ loop + 1 ];
68:}
69:  
70:/*-------------------------------------------------------------------------*
71:TGet () - Get a TDELAY object
72: *-------------------------------------------------------------------------*/
73:PRIVATE TILEDELAY *
74:TGet (
75:VOID
76:)
77:{
78:   TILEDELAY * new;
79:  
80:   if ( !free_delay )
81:      EXIT_Error ("TILEDELAY_Get() - Max ");
82:  
83:   new = free_delay;
84:   free_delay = free_delay->next;
85:  
86:   memset ( new, 0 ,sizeof ( TILEDELAY ) );
87:  
88:   new->next = &last_delay;
89:   new->prev = last_delay.prev;
90:   last_delay.prev = new;
91:   new->prev->next = new;
92:  
93:   return ( new );
94:}
95:  
96:/*-------------------------------------------------------------------------*
97:TRemove () - Remove a TDELAY Object from link list
98: *-------------------------------------------------------------------------*/
99:PRIVATE TILEDELAY *
100:TRemove (
101:TILEDELAY * sh
102:)
103:{
104:   TILEDELAY * next;
105:  
106:   next = sh->prev;
107:  
108:   sh->next->prev = sh->prev;
109:   sh->prev->next = sh->next;
110:  
111:   memset ( sh, 0, sizeof ( TILEDELAY ) );
112:  
113:   sh->next = free_delay;
114:  
115:   free_delay = sh;
116:  
117:   return ( next );
118:}
