120:/*--------------------------------------------------------------------------
121:TILE_DoDamage
122: --------------------------------------------------------------------------*/
123:PRIVATE VOID
124:TILE_DoDamage (
125:INT   mapspot,
126:INT   damage
127:)
128:{
129:   static INT mlookup [3]  = { -1, -MAP_COLS, 1 };
130:   static INT xlookup [3]  = { -1, 0, 1 };
131:   INT ix                  = ( mapspot % MAP_COLS );
132:   INT loop;
133:   INT spot;
134:   INT x;
135:
136:   for ( loop = 0; loop < 3; loop++ )
137:   {
138:      spot = mapspot + mlookup [ loop ];
139:
140:      if ( spot < 0 ) continue;
141:      if ( spot >= MAP_SIZE ) continue;
142:
143:      if ( eitems [ spot ] == titems [ spot ] ) continue;
144:
145:      x = ix + xlookup [ loop ];
146:      if ( x < 0 ) continue;
147:      if ( x >= MAP_COLS ) continue;
148:      
149:      hits [ spot ] -= damage;
150:   }
151:
152:}
