214:   startflat[1]++;
215:  
216:   startflat[2] = GLB_GetItemID ( game_start[ 2 ] );
217:   startflat[2]++;
218:  
219:   startflat[3] = GLB_GetItemID ( game_start[ 3 ] );
220:   startflat[3]++;
221:
222:}
