228:TILE_CacheLevel (
229:VOID
230:)
231:{
232:   INT      game;
233:   FLATS *  lib;
234:   DWORD    item;
235:   INT      loop;
236:
237:   TClear();
238:   g_mapleft = MAP_LEFT;
239:
240:   // SET UP START POS ON MAP =========
241:   tilepos = ( MAP_ROWS - MAP_ONSCREEN ) * MAP_COLS;
242:   tileyoff = 200 - ( MAP_ONSCREEN * MAP_BLOCKSIZE );
243:   lastspot = tspots + ( MAX_STILES - 1 );
244:
245:   scroll_flag = TRUE;
246:   last_tile = FALSE;
247:
248:   memset ( titems, 0, sizeof (  titems ) );
249:   memset ( eitems, 0, sizeof ( eitems ) );
250:   memset ( hits, 0, sizeof ( hits ) );
251:   memset ( tdead, 0, sizeof ( tdead ) );
252:
253:   // == CACHE TILES =========================
254:   for ( loop = 0; loop < MAP_SIZE; loop++ )
255:   {
256:      game = ml->map [ loop ].fgame;
257:      lib  = flatlib [ game ];
258:
259:      money [ loop ]  = lib [ ml->map [ loop ].flats ].bounty;
260:
261:      item = startflat [ game ];
262:      item += ml->map [ loop ].flats;
263:      titems [ loop ] = item;
264:      GLB_CacheItem ( item );
265:
266:      item = startflat [ game ];
267:      item += (DWORD)lib [ ml->map [ loop ].flats ].linkflat;
268:      eitems [ loop ] = item;
269:      if ( eitems [ loop ] !=  titems [ loop ] )
270:         GLB_CacheItem ( item );
271:
272:      if ( eitems [ loop ] !=  titems [ loop ] )
273:         hits [ loop ]  = lib [ ml->map [ loop ].flats ].bonus;
274:      else
275:         hits [ loop ]  = 1;
276:   }
277:}
