   startflat[0] = GLB_GetItemID ( game_start[ 0 ] );
   startflat[0]++;
  
   startflat[1] = GLB_GetItemID ( game_start[ 1 ] );
   startflat[1]++;
  
   startflat[2] = GLB_GetItemID ( game_start[ 2 ] );
   startflat[2]++;
  
   startflat[3] = GLB_GetItemID ( game_start[ 3 ] );
   startflat[3]++;

}

