TRemove (
TILEDELAY * sh
)
{
   TILEDELAY * next;
  
   next = sh->prev;
  
   sh->next->prev = sh->prev;
   sh->prev->next = sh->next;
  
   memset ( sh, 0, sizeof ( TILEDELAY ) );
  
   sh->next = free_delay;
  
   free_delay = sh;
  
   return ( next );
}

