}
  
/***************************************************************************
   Rot_Color () - Rotates color in palette
 ***************************************************************************/
VOID
Rot_Color (
BYTE *gpal,
INT snum,
INT len
)
{
   short pos, maxloop;
   char h1[3];
  
   pos = snum*3;
   maxloop=len*3;
  
   memcpy ( h1, gpal + pos, 3 );
   memcpy ( gpal + pos, gpal + pos + 3, maxloop );
   memcpy ( gpal + pos + maxloop - 3, h1, 3 );
}
  
/***************************************************************************
   InitMobj() - Inits an object to be moved
 ***************************************************************************/
VOID
InitMobj(
MOVEOBJ * cur              // INPUT : pointer to MOVEOBJ
)
{
   cur->done = FALSE;
   cur->addx = 1;
   cur->addy = 1;
  
   cur->delx = cur->x2 - cur->x;
   cur->dely = cur->y2 - cur->y;
  
   if ( cur->delx < 0 )
   {
      cur->delx = -cur->delx;
      cur->addx = -cur->addx;
   }
   if ( cur->dely < 0 )
   {
      cur->dely = -cur->dely;
      cur->addy = -cur->addy;
   }
  
   if ( cur->delx >= cur->dely )
   {
      cur->err = -(cur->dely>>1);
      cur->maxloop = cur->delx + 1;
   }
   else
   {
      cur->err = (cur->delx>>1);
      cur->maxloop = cur->dely + 1;
   }
}
  
/***************************************************************************
   MoveMobj() - gets next postion for an Object
 ***************************************************************************/
VOID
MoveMobj(
MOVEOBJ * cur              // INPUT : pointer to MOVEOBJ
)
{
   if ( cur->maxloop == 0 )
   {
      cur->done = TRUE;
      return;
   }
  
   if ( cur->delx >= cur->dely )
   {
      cur->x += cur->addx;
      cur->err += cur->dely;
  
      if ( cur->err > 0 )
      {
         cur->y += cur->addy;
         cur->err -= cur->delx;
      }
   }
   else
   {
      cur->y += cur->addy;
      cur->err += cur->delx;
  
      if ( cur->err > 0 )
      {
         cur->x += cur->addx;
         cur->err -= cur->dely;
      }
   }
  
   cur->maxloop--;
}

/***************************************************************************
   MoveSobj() - gets next postion for an Object at speed
 ***************************************************************************/
INT
MoveSobj(
MOVEOBJ * cur,             // INPUT : pointer to MOVEOBJ
INT       speed            // INPUT : speed to plot at
)
{
   if ( speed == 0 ) return ( 0 );

   if ( cur->delx >= cur->dely )
   {
      while ( speed )
      {
         speed--;
         cur->maxloop--;
         cur->x += cur->addx;
         cur->err += cur->dely;
  
         if ( cur->err > 0 )
         {
            cur->y += cur->addy;
            cur->err -= cur->delx;
         }
      }
   }
   else
   {
      while ( speed )
      {
         speed--;
         cur->maxloop--;
         cur->y += cur->addy;
         cur->err += cur->delx;
  
         if ( cur->err > 0 )
         {
            cur->x += cur->addx;
            cur->err -= cur->dely;
         }
      }
   }
  
   if ( cur->maxloop < 1 )
      cur->done = TRUE;

   return ( speed );
}

/***************************************************************************
RAP_PrintNum()
 ***************************************************************************/
VOID
RAP_PrintNum(
INT x,
INT y,
CHAR * str
)
{
   INT       maxloop;
   INT       num;

   maxloop = strlen ( str );

   GFX_PutSprite ( numbers[10], x, y );
   x += 9;

   while ( maxloop-- )
   {
      num = (INT)((*str)-'0');

      if ( num < 11 && num >=0 )
         GFX_PutSprite ( numbers[num], x ,y );

      x += 8;
      str++;
   }
}

/***************************************************************************
RAP_DisplayShieldLevel (
 ***************************************************************************/
VOID
RAP_DisplayShieldLevel (
INT xpos,
INT level
)
{
   INT    loop;
   BYTE * outbuf;
   DWORD  addx;
   DWORD  curs;

   outbuf = displayscreen + ylookup[199];
   outbuf += xpos;

   addx = ( SHIELD_COLOR_RUN << 16 ) / MAX_SHIELD;
   curs = 0;

   for ( loop = 0; loop < MAX_SHIELD; loop++ )
   {
      if ( loop < level )
         memset ( outbuf, 74 - ( curs >> 16 ) ,4 );
      else
         memset ( outbuf, 0, 4 );

      curs += addx;

      outbuf -= 640;
   }
}

