            cur->err -= cur->dely;
         }
      }
   }
  
   if ( cur->maxloop < 1 )
      cur->done = TRUE;

   return ( speed );
}

/***************************************************************************
RAP_PrintNum()
 ***************************************************************************/
VOID
RAP_PrintNum(
INT x,
INT y,
CHAR * str
)
{
   INT       maxloop;
   INT       num;

   maxloop = strlen ( str );

   GFX_PutSprite ( numbers[10], x, y );
   x += 9;

   while ( maxloop-- )
   {
      num = (INT)((*str)-'0');

      if ( num < 11 && num >=0 )
         GFX_PutSprite ( numbers[num], x ,y );

      x += 8;
      str++;
   }
}

/***************************************************************************
RAP_DisplayShieldLevel (
 ***************************************************************************/
VOID
RAP_DisplayShieldLevel (
INT xpos,
INT level
)
{
   INT    loop;
   BYTE * outbuf;
   DWORD  addx;
   DWORD  curs;

   outbuf = displayscreen + ylookup[199];
   outbuf += xpos;

   addx = ( SHIELD_COLOR_RUN << 16 ) / MAX_SHIELD;
   curs = 0;

   for ( loop = 0; loop < MAX_SHIELD; loop++ )
   {
      if ( loop < level )
         memset ( outbuf, 74 - ( curs >> 16 ) ,4 );
      else
         memset ( outbuf, 0, 4 );

      curs += addx;

      outbuf -= 640;
   }
}

