RAP_GetShipPic (
VOID
)
{
   INT   loop;
   BOOL  lightflag = TRUE;

   // GAME 2 wave 8
   if ( cur_game == 1 && game_wave [ cur_game ] == 7 )
      lightflag = FALSE;

   // GAME 3 wave 3
   if ( cur_game == 2 && game_wave [ cur_game ] == 2 )
      lightflag = FALSE;

   for ( loop = 0; loop < 7; loop++ )
   {
