   maxloop = strlen ( str );

   GFX_PutSprite ( numbers[10], x, y );
   x += 9;

   while ( maxloop-- )
   {
      num = (INT)((*str)-'0');

      if ( num < 11 && num >=0 )
         GFX_PutSprite ( numbers[num], x ,y );

      x += 8;
      str++;
   }
}

