   draw_player = TRUE;

   srand ( ( 1024 * game_wave [ cur_game ] ) );

   fadeflag = FALSE;
   end_fadeflag = FALSE;
   KBD_Clear();
   IMS_StartAck();
   BUT_1 = FALSE;
   BUT_2 = FALSE;
   BUT_3 = FALSE;
   BUT_4 = FALSE;
  
   playerx = PLAYERINITX;
   playery = PLAYERINITY;
   PTR_SetPos ( playerx, playery );
   IPT_Start();

   RAP_GetShipPic();
   BONUS_Clear();
   ANIMS_Clear();
   SHOTS_Clear();
   ESHOT_Clear();

   memcpy ( gpal, palette, 768 );
   GFX_FadeOut ( 0, 0, 0, 2 );
  
   memset ( displaybuffer, 0, 64000 );
   memset ( displayscreen, 0, 64000 );

   local_cnt = FRAME_COUNT;
  
   g_flash = 0;
   g_oldsuper     = EMPTY;
   g_oldshield    = EMPTY;
   startendwave   = EMPTY;

   if ( demo_flag == DEMO_RECORD )
      DEMO_StartRec();

   // == CLEAR ALL BUTTONS ===========================

   start_score = plr.score;
   IMS_StartAck();
   memset ( buttons, 0, sizeof ( buttons ) );

   for (;;)
   {
      SHADOW_Clear();
  
      IPT_MovePlayer();
  
      if ( KBD_IsKey ( SC_F1 ) )
      {
         SWD_SetClearFlag ( FALSE );
         IPT_End();
         HELP_Win ( "OVERVW06_TXT" );
         memset ( displayscreen, 0, 64000 );
         IPT_Start();
         g_oldsuper = EMPTY;
         g_oldshield = EMPTY;
         RAP_ClearSides();
         RAP_DisplayStats();
