      // == COLOR 252 & 253 ======== BLINKING REG AND GREEN
      if ( palcnt % 2 )
      {
         offset =  ( 252 * 3 );
         pal1 = gpal + offset;
         pal2 = palette + offset;

         if ( blink & 1 )
         {
            memcpy ( pal1, pal2, 3 );
            pal1+=3;
            pal2+=3;
            memset ( pal1, 0, 3 );
         }
         else
         {
            memset ( pal1, 0, 3 );
            pal1+=3;
            pal2+=3;
            memcpy ( pal1, pal2, 3 );
         }

         blink++;
      }

      // == COLOR 254 ======== BLINKING BLUE
      offset =  ( 254 * 3 );
      if ( random ( 3 ) == 0 )
      {
         pal1 = gpal + offset;
         pal2 = palette + offset;
         memcpy ( pal1, pal2, 3 );
      }
      else
      {
         pal1 = gpal + offset;
         memset ( pal1, 0, 3 );
      }

